import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        String[] players = {"Ana", "Ben", "Cal", "Dee", "Eli", "Fay"};
        int[] teamOf = {0, 1, 0, 2, 1, 0};

        List<List<String>> teams = new ArrayList<>();
        for (int t = 0; t < 3; t++) {
            teams.add(new ArrayList<>());
        }

        for (int i = 0; i < players.length; i++) {
            teams.get(teamOf[i]).add(players[i]);
        }

        for (int t = 0; t < teams.size(); t++) {
            System.out.println("Team " + (t + 1) + " (" + teams.get(t).size() + "): " + teams.get(t));
        }
        System.out.println("Captain of team 2: " + teams.get(1).get(0));
    }
}
